package com.sharehope.submission.controller;
import com.sharehope.submission.dto.PublicSubmissionResponse; import com.sharehope.submission.repository.PublicSubmissionRepository; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin/submissions") @RequiredArgsConstructor
public class AdminSubmissionController{private final PublicSubmissionRepository repository;@GetMapping public List<PublicSubmissionResponse> list(){return repository.findAllByOrderByCreatedAtDesc().stream().map(PublicSubmissionResponse::from).toList();}
@PatchMapping("/{id}/status") public PublicSubmissionResponse status(@PathVariable java.util.UUID id,@RequestBody java.util.Map<String,String> body){String status=body.getOrDefault("status","");if(!java.util.Set.of("NEW","CONTACTED","ACCEPTED","CLOSED").contains(status))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Invalid status");var value=repository.findById(id).orElseThrow(()->new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.NOT_FOUND));value.setStatus(status);return PublicSubmissionResponse.from(repository.save(value));}}
